#[derive(PartialEq, Eq, Debug)]
pub enum Bucket {
    One,
    Two,
}

/// A struct to hold your results in.
#[derive(PartialEq, Eq, Debug)]
pub struct BucketStats {
    /// The total number of "moves" it should take to reach the desired number of liters, including
    /// the first fill.
    pub moves: u8,
    /// Which bucket should end up with the desired number of liters? (Either "one" or "two")
    pub goal_bucket: Bucket,
    /// How many liters are left in the other bucket?
    pub other_bucket: u8,
}

/// Solve the bucket problem
pub fn solve(
    capacity_1: u8,
    capacity_2: u8,
    goal: u8,
    start_bucket: &Bucket,
) -> Option<BucketStats> {
    if goal > capacity_1.max(capacity_2) {
        return None;
    }

    let initial: (u8, u8) = match start_bucket {
        Bucket::One => (capacity_1, 0),
        Bucket::Two => (0, capacity_2),
    };

    // The state the puzzle forbids: the starting bucket is empty while the
    // other bucket is full.
    let forbidden: (u8, u8) = match start_bucket {
        Bucket::One => (0, capacity_2),
        Bucket::Two => (capacity_1, 0),
    };

    let mut visited = vec![vec![false; capacity_2 as usize + 1]; capacity_1 as usize + 1];
    visited[initial.0 as usize][initial.1 as usize] = true;

    let mut queue: VecDeque<((u8, u8), u8)> = VecDeque::new();
    queue.push_back((initial, 1));

    while let Some(((b1, b2), moves)) = queue.pop_front() {
        if b1 == goal {
            return Some(BucketStats {
                moves,
                goal_bucket: Bucket::One,
                other_bucket: b2,
            });
        }
        if b2 == goal {
            return Some(BucketStats {
                moves,
                goal_bucket: Bucket::Two,
                other_bucket: b1,
            });
        }

        let candidates = [
            (capacity_1, b2),                                    // fill one
            (b1, capacity_2),                                    // fill two
            (0, b2),                                              // empty one
            (b1, 0),                                              // empty two
            pour(b1, b2, capacity_2),                            // pour one into two
            {
                let (two, one) = pour(b2, b1, capacity_1);
                (one, two)
            }, // pour two into one
        ];

        for state in candidates {
            if state == forbidden || state == (b1, b2) {
                continue;
            }
            if !visited[state.0 as usize][state.1 as usize] {
                visited[state.0 as usize][state.1 as usize] = true;
                queue.push_back((state, moves + 1));
            }
        }
    }

    None
}

/// Pour from a bucket holding `from` liters into a bucket holding `into`
/// liters with capacity `into_cap`, returning the resulting (from, into).
fn pour(from: u8, into: u8, into_cap: u8) -> (u8, u8) {
    let amount = from.min(into_cap - into);
    (from - amount, into + amount)
}
"}

